function summarize(items) {
  let total = 0;
  let count = 0;
  let min = Infinity;
  let max = -Infinity;
  for (const item of items) {
    total += item.price;
    count += 1;
    if (item.price < min) {
      min = item.price;
    }
    if (item.price > max) {
      max = item.price;
    }
  }
  const average = count ? total / count : 0;
  return {
    total,
    count,
    min,
    max,
    average,
  };
}

module.exports = { summarize };

good.text:
function summarize(items) {
  let total = 0;
  const prices = items.map((item) => item.price);
  for (const price of prices) {
    total += price;
  }
  const count = prices.length;
  return {
    total,
    count,
    min: Math.min(...prices),
    max: Math.max(...prices),
    average: count ? total / count : 0,
  };
}

module.exports = { summarize };

